//go:build live

package live

import (
	"encoding/json"
	"github.com/tokenbeat-lab/barness/ai"
	"github.com/tokenbeat-lab/barness/ai/internal/testkit/evidence"
	"os"
	"reflect"
)

func glmJSONEqual(a, b any) bool { return reflect.DeepEqual(a, b) }
func glmJSONValue(v any) any {
	raw, _ := json.Marshal(v)
	var out any
	json.Unmarshal(raw, &out)
	return out
}

// These exact paths are generated by the Host. Never walk arbitrary keys named
// id/requestId: upstream IDs/signatures in messages, arguments and payloads stay.
func glmNormalizeResult(v map[string]any) {
	if msg, ok := v["message"].(map[string]any); ok {
		delete(msg, "timestamp")
		delete(msg, "durationMs")
	}
	if metadata, ok := v["metadata"].(map[string]any); ok {
		glmNormalizeMetadata(metadata)
	}
}
func glmNormalizeMetadata(metadata map[string]any) {
	delete(metadata, "requestId")
	if attempts, ok := metadata["attempts"].([]any); ok {
		for _, v := range attempts {
			if attempt, ok := v.(map[string]any); ok {
				delete(attempt, "attemptId")
			}
		}
	}
}
func glmNormalizeObservations(observations []map[string]any) {
	for _, o := range observations {
		delete(o, "time")
		delete(o, "duration")
		if call, ok := o["call"].(map[string]any); ok {
			glmNormalizeMetadata(call)
		}
		if attempt, ok := o["attempt"].(map[string]any); ok {
			delete(attempt, "attemptId")
		}
	}
}
func (s *glmCaptureReplay) compare(cs *evidence.Case, id string, result ai.Result, err error, observations []ai.Observation) {
	s.mu.Lock()
	wireEqual := s.wireMatched[id]
	s.mu.Unlock()
	cs.Record("capture-request-comparison", map[string]any{"equal": wireEqual, "expectedPayload": json.RawMessage(s.calls[id].exchange.RequestBody), "target": s.calls[id].exchange.URL, "normalization": "none; every payload field and target compared"})
	cs.Check("exact captured final payload including all tool/native IDs", wireEqual, "wire differs")
	expected := glmJSONValue(s.calls[id].result).(map[string]any)
	actual := glmJSONValue(map[string]any{"result": result, "error": errText(err)}).(map[string]any)
	expectedResult := expected["result"].(map[string]any)
	actualResult := actual["result"].(map[string]any)
	// Deliberate expectation mutations are available only in the no-network
	// process test. They prove provider identities/native signatures stay exact.
	fault := os.Getenv("BARNESS_GLM_REPLAY_FAULT")
	if fault == "provider-id" {
		expectedResult["message"].(map[string]any)["responseId"] = "changed-upstream-response-id"
	}
	if fault == "native-signature" {
		message := expectedResult["message"].(map[string]any)
		parts, _ := message["content"].([]any)
		for _, v := range parts {
			part, _ := v.(map[string]any)
			if _, ok := part["thinkingSignature"]; ok {
				part["thinkingSignature"] = "changed-native-signature"
				break
			}
		}
	}
	glmNormalizeResult(expectedResult)
	glmNormalizeResult(actualResult)
	equal := glmJSONEqual(expected, actual)
	cs.Record("capture-result-comparison", map[string]any{"equal": equal, "expected": expected, "actual": actual, "normalization": "message.timestamp/durationMs, metadata.requestId and metadata.attempts[*].attemptId only"})
	cs.Check("exact captured Result including all upstream IDs and native signatures", equal, "captured public Result differs")
	expectedObs := glmJSONValue(s.calls[id].observations)
	actualObs := glmJSONValue(observations)
	convert := func(v any) []map[string]any {
		var out []map[string]any
		for _, item := range v.([]any) {
			out = append(out, item.(map[string]any))
		}
		return out
	}
	want, got := convert(expectedObs), convert(actualObs)
	glmNormalizeObservations(want)
	glmNormalizeObservations(got)
	same := glmJSONEqual(want, got)
	cs.Record("capture-observer-comparison", map[string]any{"equal": same, "expected": want, "actual": got})
	cs.Check("exact captured Observer metadata except Host clock/local IDs", same, "captured Observer differs")
}
func (s *glmCaptureReplay) cancelMatches(id string, event ai.Event) bool {
	var message ai.AssistantMessage
	switch e := event.(type) {
	case ai.TextDeltaEvent:
		message = e.Partial.Snapshot()
	case ai.ThinkingDeltaEvent:
		message = e.Partial.Snapshot()
	default:
		return false
	}
	if glmJSONEqual(glmJSONValue(message.Content), s.calls[id].cancelContent) {
		return true
	}
	select {
	case s.ack <- struct{}{}:
	default:
	}
	return false
}
